"""Example 5: C3 linearization and MRO inspection."""

class A:
    def greet(self) -> str: return "A"

class B(A):
    def greet(self) -> str: return "B -> " + super().greet()

class C(A):
    def greet(self) -> str: return "C -> " + super().greet()

class D(B, C):
    def greet(self) -> str: return "D -> " + super().greet()

print("=== D's MRO ===")
for cls in D.__mro__:
    print(f"  {cls.__name__}")

print("\n=== Calling greet() walks the MRO ===")
print(f"  D().greet() = {D().greet()}")
# D -> B -> C -> A
# `super()` in B returns the next class in D's MRO (which is C, not A!)

print("\n=== Invalid MRO raises TypeError ===")
try:
    class X(A, B): pass  # A would have to come before B — invalid
except TypeError as e:
    print(f"  TypeError: {e}")
```

**Key insight:** `super()` doesn't mean "my parent" — it means "the next class in **the calling instance's MRO**." This is why `super()` works correctly even in multiple inheritance.

```python
"""Example 7: See the free-list optimization by measuring alloc timing."""
import timeit

# Tuples have a free list — allocating small tuples is fast.
def alloc_tuples():
    for _ in range(10000):
        x = (1, 2, 3)

# Lists have a free list too, but each list object has more overhead.
def alloc_lists():
    for _ in range(10000):
        x = [1, 2, 3]

# Dicts (3.6+) also benefit from free lists.
def alloc_dicts():
    for _ in range(10000):
        x = {"a": 1, "b": 2, "c": 3}

# Custom class instances — NO free list (in most CPython versions).
class Point:
    __slots__ = ("x", "y", "z")
    def __init__(self):
        self.x = 1
        self.y = 2
        self.z = 3

def alloc_objects():
    for _ in range(10000):
        x = Point()

t_tup = timeit.timeit(alloc_tuples, number=100)
t_lst = timeit.timeit(alloc_lists, number=100)
t_dct = timeit.timeit(alloc_dicts, number=100)
t_obj = timeit.timeit(alloc_objects, number=100)

print(f"  tuples (free list): {t_tup:.2f}s")
print(f"  lists  (free list): {t_lst:.2f}s")
print(f"  dicts  (free list): {t_dct:.2f}s")
print(f"  objects (no list):  {t_obj:.2f}s")
print(f"\n  Tuple alloc is ~{t_obj/t_tup:.1f}x faster than custom object alloc")
```

**Why this matters:** in tight loops, prefer built-in containers (especially tuples for fixed-size records) — they're dramatically cheaper than custom classes thanks to free lists and smaller header overhead.
